-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/ahtUrhgan/BLU_AF1_Beginnings.lua"]={["Path"]="scripts/quests/ahtUrhgan/BLU_AF1_Beginnings.lua",["SHA256"]="691da6dd8b72dfd8b59fc2ccc940bfcdcdfc62f0cc811e03aff6cfe96e72a115",["Text"]="-----------------------------------\n-- Beginnings (BLU AF1)\n-----------------------------------\n-- Log ID: 6, Quest ID: 21\n-- Waoud   : !pos 65 -6 -78 50\n-- Daswil  : !pos -208.720 -12.889 -779.713 52\n-- Meyaada : !pos 22.446 -7.920 573.390 54\n-- Nahshib : !pos -274.334 -9.287 -64.255 79\n-- Nareema : !pos 518.387 -24.707 -467.297 79\n-- Waudeen : !pos 673.882 -23.995 367.604 61\n-----------------------------------\n-- Omens opens one minute after this quest completes.\n-- The June 7, 2016 version update shortened the wait from one Earth day.\n--\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-----------------------------------\nlocal whitegateID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.BEGINNINGS)\n\nquest.reward =\n{\n    item  = xi.item.IMMORTALS_SCIMITAR,\n    title = xi.title.BRANDED_BY_THE_FIVE_SERPENTS,\n}\n\nlocal brandKeyItems =\n{\n    xi.keyItem.BRAND_OF_THE_SPRINGSERPENT,\n    xi.keyItem.BRAND_OF_THE_GALESERPENT,\n    xi.keyItem.BRAND_OF_THE_FLAMESERPENT,\n    xi.keyItem.BRAND_OF_THE_SKYSERPENT,\n    xi.keyItem.BRAND_OF_THE_STONESERPENT,\n}\n\nlocal function hasRequiredBrands(player)\n    for _, keyItem in ipairs(brandKeyItems) do\n        if not player:hasKeyItem(keyItem) then\n            return false\n        end\n    end\n\n    return true\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedMission(xi.mission.log_id.TOAU, xi.mission.id.toau.IMMORTAL_SENTRIES) and\n                player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.AN_EMPTY_VESSEL) and\n                player:getMainJob() == xi.job.BLU and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL and\n                xi.quest.getVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.AN_EMPTY_VESSEL, 'completeEvent') == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Waoud'] = quest:progressEvent(705),\n\n            onEventFinish =\n            {\n                [705] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:getMainJob() == xi.job.BLU\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Waoud'] =\n            {\n                onTrigger = function(player, npc)\n                    if hasRequiredBrands(player) then\n                        return quest:progressEvent(707)\n                    else\n                        return quest:progressEvent(706, player:getGil())\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [706] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        player:getGil() >= 1000\n                    then\n                        player:delGil(1000)\n                        player:messageSpecial(whitegateID.text.PAY_DIVINATION)\n                    end\n                end,\n\n                [707] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setMustZone(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OMENS)\n                        xi.quest.setVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OMENS, 'Timer', GetSystemTime() + 60) -- 1 minute wait time\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['Meyaada'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.BRAND_OF_THE_SPRINGSERPENT) then\n                        return quest:progressEvent(10)\n                    else\n                        return quest:event(11):importantEvent()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BRAND_OF_THE_SPRINGSERPENT)\n                end,\n            },\n        },\n\n        [xi.zone.BHAFLAU_THICKETS] =\n        {\n            ['Daswil'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.BRAND_OF_THE_SKYSERPENT) then\n                        return quest:progressEvent(8)\n                    else\n                        return quest:event(9):importantEvent()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [8] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BRAND_OF_THE_SKYSERPENT)\n                end,\n            },\n        },\n\n        [xi.zone.CAEDARVA_MIRE] =\n        {\n            ['Nahshib'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.BRAND_OF_THE_GALESERPENT) then\n                        return quest:progressEvent(10)\n                    else\n                        return quest:event(11):importantEvent()\n                    end\n                end,\n            },\n\n            ['Nareema'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.BRAND_OF_THE_STONESERPENT) then\n                        return quest:progressEvent(12)\n                    else\n                        return quest:event(13):importantEvent()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BRAND_OF_THE_GALESERPENT)\n                end,\n\n                [12] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BRAND_OF_THE_STONESERPENT)\n                end,\n            },\n        },\n\n        [xi.zone.MOUNT_ZHAYOLM] =\n        {\n            ['Waudeen'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.BRAND_OF_THE_FLAMESERPENT) then\n                        return quest:progressEvent(10)\n                    else\n                        return quest:event(11):importantEvent()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BRAND_OF_THE_FLAMESERPENT)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/BLU_AF2_Omens.lua"]={["Path"]="scripts/quests/ahtUrhgan/BLU_AF2_Omens.lua",["SHA256"]="ededea42195a9f935ab68b60e71739bf496cd3840ad80f82d5d9efedafee0dee",["Text"]="-----------------------------------\n-- Omens (BLU AF2)\n-----------------------------------\n-- Log ID: 6, Quest ID: 22\n-- Waoud           : !pos 65 -6 -78 50\n-- Lathuya         : !pos -95.081 -6 31.638 50\n-- Aydeewa (Blank) : !pos 342.129 36.509 -24.856 68\n-----------------------------------\n-- Transformations opens one minute after this quest completes.\n-- The June 7, 2016 version update shortened the wait from one Earth day.\n--\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-----------------------------------\nlocal whitegateID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OMENS)\n\nquest.reward =\n{\n    item = xi.item.MAGUS_CHARUQS,\n    title = xi.title.IMMORTAL_LION,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.BEGINNINGS) and\n                player:getMainJob() == xi.job.BLU and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Waoud'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getMustZone(player) or\n                        GetSystemTime() < quest:getVar(player, 'Timer')\n                    then\n                        return\n                    end\n\n                    return quest:progressEvent(710)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [710] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Waoud'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(712)\n                    elseif questProgress == 0 then\n                        return quest:progressEvent(711, player:getGil())\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(713, player:getGil())\n                    end\n                end,\n            },\n\n            ['Lathuya'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 2 then\n                        return quest:progressEvent(714)\n                    elseif questProgress == 3 then\n                        return quest:progressEvent(715)\n                    elseif questProgress == 4 then\n                        return quest:progressEvent(716)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [711] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        player:getGil() >= 1000\n                    then\n                        player:delGil(1000)\n                        player:messageSpecial(whitegateID.text.PAY_DIVINATION)\n                    end\n                end,\n\n                [712] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SEALED_IMMORTAL_ENVELOPE)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [713] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        player:getGil() >= 1000\n                    then\n                        player:delGil(1000)\n                        player:messageSpecial(whitegateID.text.PAY_DIVINATION)\n                    end\n                end,\n\n                [714] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [716] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.SEALED_IMMORTAL_ENVELOPE)\n\n                        xi.quest.setMustZone(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.TRANSFORMATIONS)\n                        xi.quest.setVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.TRANSFORMATIONS, 'Timer', GetSystemTime() + 60) -- 1 minute wait time\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.AYDEEWA_SUBTERRANE] =\n        {\n            ['blank_omens'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(9)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [9] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.NAVUKGO_EXECUTION_CHAMBER] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if\n                        player:getLocalVar('battlefieldWin') == xi.battlefield.id.OMENS and\n                        quest:getVar(player, 'Prog') == 0\n                    then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Lathuya'] = quest:event(771):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/BLU_AF3_Transformations.lua"]={["Path"]="scripts/quests/ahtUrhgan/BLU_AF3_Transformations.lua",["SHA256"]="bd39946c70f08a661e4e4d791735ff47f8d527ecdc55c71de2eda6ac02e0adaa",["Text"]="-----------------------------------\n-- Transformations (BLU AF3)\n-----------------------------------\n-- Log ID: 6, Quest ID: 23\n-- Waoud              : !pos 65 -6 -78 50\n-- Imperial Whitegate : !pos 152 -2 0 50\n-- Alzadaal (Blank)   : !pos -529.704 0 649.682 72\n-----------------------------------\n-- The Beast Within opens one minute after this quest completes.\n-- The June 7, 2016 version update shortened the wait from one Earth day.\n--\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-----------------------------------\nlocal alzadaalID  = zones[xi.zone.ALZADAAL_UNDERSEA_RUINS]\nlocal whitegateID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.TRANSFORMATIONS)\n\nquest.reward =\n{\n    item  = xi.item.MAGUS_KEFFIYEH,\n    title = xi.title.PARAGON_OF_BLUE_MAGE_EXCELLENCE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OMENS) and\n                player:getMainJob() == xi.job.BLU and\n                player:getMainLvl() >= xi.settings.main.AF3_QUEST_LEVEL\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Waoud'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getMustZone(player) or\n                        GetSystemTime() < quest:getVar(player, 'Timer')\n                    then\n                        return\n                    end\n\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(720, player:getGil())\n                    else\n                        return quest:progressEvent(721, player:getGil())\n                    end\n                end,\n            },\n\n            ['Imperial_Whitegate'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(722)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [720] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        player:getGil() >= 1000\n                    then\n                        player:delGil(1000)\n                        player:messageSpecial(whitegateID.text.PAY_DIVINATION)\n\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [721] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        player:getGil() >= 1000\n                    then\n                        player:delGil(1000)\n                        player:messageSpecial(whitegateID.text.PAY_DIVINATION)\n                    end\n                end,\n\n                [722] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    player:setCharVar('[BLUAF]Remaining', 7) -- Player can now craft BLU armor\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Waoud'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(723, player:getGil())\n                end,\n            },\n\n            onEventFinish =\n            {\n                [723] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        player:getGil() >= 1000\n                    then\n                        player:delGil(1000)\n                        player:messageSpecial(whitegateID.text.PAY_DIVINATION)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.ALZADAAL_UNDERSEA_RUINS] =\n        {\n            ['blank_transformations'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if\n                        questProgress == 3 and\n                        not GetMobByID(alzadaalID.mob.NEPIONIC_SOULFLAYER):isSpawned()\n                    then\n                        return quest:progressEvent(4)\n                    elseif questProgress == 4 then\n                        return quest:progressEvent(5)\n                    end\n                end,\n            },\n\n            ['Nepionic_Soulflayer'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n            },\n\n            onTriggerAreaEnter =\n            {\n                [24] = function(player, triggerArea)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(2)\n                    end\n                end,\n\n                [25] = function(player, triggerArea)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(3)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [3] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [4] = function(player, csid, option, npc)\n                    npcUtil.popFromQM(player, npc, alzadaalID.mob.NEPIONIC_SOULFLAYER, { hide = 0 })\n                end,\n\n                [5] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THE_BEAST_WITHIN, 'Timer', GetSystemTime() + 60) -- 1 minute wait time\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/BLU_LB_The_Beast_Within.lua"]={["Path"]="scripts/quests/ahtUrhgan/BLU_LB_The_Beast_Within.lua",["SHA256"]="38fadc859939101e88cfe6e1162b96dec26fbffe871c5b507524e7cac286cd42",["Text"]="-----------------------------------\n-- The Beast Within (BLU LB)\n-----------------------------------\n-- Log ID: 6, Quest ID: 40\n-- Waoud: !pos 65 -6 -78 50\n-----------------------------------\n-- Opens one minute after Transformations completes.\n-- The June 7, 2016 version update shortened the wait from one Earth day.\n--\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-----------------------------------\nlocal whitegateID     = zones[xi.zone.AHT_URHGAN_WHITEGATE]\nlocal jadeSepulcherID = zones[xi.zone.JADE_SEPULCHER]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THE_BEAST_WITHIN)\n\nquest.reward =\n{\n    title = xi.title.MASTER_OF_AMBITION,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.TRANSFORMATIONS) and\n                player:getMainJob() == xi.job.BLU and\n                player:getMainLvl() >= 66\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Waoud'] =\n            {\n                onTrigger = function(player, npc)\n                    if GetSystemTime() < quest:getVar(player, 'Timer') then\n                        return\n                    end\n\n                    return quest:progressEvent(760)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [760] = function(player, csid, option, npc)\n                    if option == 0 then\n                        return quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:getMainJob() == xi.job.BLU and\n                player:getMainLvl() >= 66\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Waoud'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(761)\n                end,\n            },\n\n            ['Imperial_Whitegate'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if trade:getItemQty(xi.item.BLUE_MAGES_TESTIMONY) > 0 then\n                        if quest:getVar(player, 'Prog') == 2 then\n                            return quest:progressEvent(763)\n                        else\n                            return quest:progressEvent(762)\n                        end\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [761] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:updateEvent(player:getGil()) -- The event automtically gives the correct option depending on the player's gil.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [761] = function(player, csid, option, npc)\n                    if option ~= 1 then\n                        return\n                    end\n\n                    if player:getGil() < 1000 then\n                        return\n                    end\n\n                    player:delGil(1000)\n                    player:messageSpecial(whitegateID.text.PAY_DIVINATION)\n                end,\n\n                [762] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                        player:setPos(300.280, -0.853, -177.745, 63, 67) -- Teleport to Jade Sepulcher\n                    end\n                end,\n\n                [763] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:setPos(300.280, -0.853, -177.745, 63, 67) -- Teleport to Jade Sepulcher\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.JADE_SEPULCHER] =\n        {\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 1 then\n                    return 2\n                end\n            end,\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [6] = function(player, csid, option, npc)\n                    if player:getLevelCap() == 70 then\n                        player:setLevelCap(75)\n                        player:messageSpecial(jadeSepulcherID.text.YOUR_LEVEL_LIMIT_IS_NOW_75)\n                    end\n\n                    npcUtil.giveItem(player, { xi.item.SCROLL_OF_INSTANT_WARP })\n                    quest:complete(player)\n                end,\n\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.BEAST_WITHIN then\n                        player:startEvent(6)\n                    end\n                end,\n            },\n        },\n\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/COR_AF1_Equipped_for_All_Occasions.lua"]={["Path"]="scripts/quests/ahtUrhgan/COR_AF1_Equipped_for_All_Occasions.lua",["SHA256"]="9ebfae85d77a04cfdd304c510fc6bbacfccace766af8b75a23319f104fa4b529",["Text"]="-----------------------------------\n-- Equipped for All Occasions\n-- Corsair AF1 Quest\n-----------------------------------\n-- Log ID: 6, Quest ID: 24\n-- qm6 (H-10/Boat)  : !pos 468.767 -12.292 111.817 54\n-- _5i0 (Iron Door) : !pos 247.735 18.499 -142.267 198\n-- Ratihb           : !pos 75.225 -6.000 -137.203 50\n-----------------------------------\nlocal mazeID = zones[xi.zone.MAZE_OF_SHAKHRAMI]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.EQUIPPED_FOR_ALL_OCCASIONS)\n\nquest.reward =\n{\n    item  = xi.item.TRUMP_GUN,\n}\n\nquest.sections =\n{\n    -- Section: Quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainJob() == xi.job.COR and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL\n        end,\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['qm6'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(228)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [228] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MAZE_OF_SHAKHRAMI] =\n        {\n            ['_5i0'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        npcUtil.popFromQM(player, npc, mazeID.mob.LOST_SOUL, { hide = 0 })\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(66)\n                    end\n                end,\n            },\n\n            ['Lost_Soul'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [66] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.WHEEL_LOCK_TRIGGER)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['qm6'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(231)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [231] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.WHEEL_LOCK_TRIGGER)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ratihb'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Variable 'Stage' is set on quest 'Luck of the Draw', on section 'Quest completed'.\n                    if quest:getVar(player, 'Prog') == 4 and quest:getVar(player, 'Stage') == 1 then\n                        return quest:progressEvent(772)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [772] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/COR_AF2_Navigating_the_Unfriendly_Seas.lua"]={["Path"]="scripts/quests/ahtUrhgan/COR_AF2_Navigating_the_Unfriendly_Seas.lua",["SHA256"]="732c71dabe1535c766614670b79a4192a836707bde2c9ab2bfc3ab98d0d05896",["Text"]="-----------------------------------\n-- Navigating the Unfriendly Seas\n-- Corsair AF2 Quest\n-----------------------------------\n-- !addquest 6 25\n-- qm6 (H-10 / Boat): !pos 468.767 -12.292 111.817 54\n-- Leleroon         : !pos -14.687 0.000 25.114 53\n-- Leypoint         : !pos -200.027 -8.500 80.058 51\n-----------------------------------\nlocal wajaomID = zones[xi.zone.WAJAOM_WOODLANDS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.NAVIGATING_THE_UNFRIENDLY_SEAS)\n\nquest.reward =\n{\n    item = xi.item.CORSAIRS_CULOTTES,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.EQUIPPED_FOR_ALL_OCCASIONS) == xi.questStatus.QUEST_COMPLETED and\n                player:getMainJob() == xi.job.COR and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL\n        end,\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['qm6'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(232)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [232] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Leleroon'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        trade:getItemQty(xi.item.HYDROGAUGE) > 0\n                    then\n                        return quest:progressEvent(283)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') >= 1 and\n                        quest:getVar(player, 'Prog') < 3\n                    then\n                        return quest:event(292)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [283] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            ['Leypoint'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeHasExactly(trade, xi.item.HYDROGAUGE)\n                    then\n                        player:confirmTrade()\n                        quest:setVar(player, 'Prog', 2)\n                        quest:setVar(player, 'Wait', GetSystemTime() + 60) -- 1 minute wait time\n                        return quest:messageSpecial(wajaomID.text.PLACE_HYDROGAUGE, xi.item.HYDROGAUGE)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        if quest:getVar(player, 'Wait') > GetSystemTime() then\n                            return quest:messageSpecial(wajaomID.text.ENIGMATIC_LIGHT, xi.item.HYDROGAUGE)\n                        else\n                            return quest:progressEvent(508)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [508] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    quest:setVar(player, 'Wait', 0)\n                end,\n            },\n        },\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['qm6'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(233)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [233] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/COR_AF3_Against_All_Odds.lua"]={["Path"]="scripts/quests/ahtUrhgan/COR_AF3_Against_All_Odds.lua",["SHA256"]="49f6e370531446c2bc614e0bbd5b8b124a9e3c0b225af41e500c85494cb92190",["Text"]="-----------------------------------\n-- Against All Odds\n-- Corsair AF3 Quest\n-----------------------------------\n-- !addquest 6 26\n-- Ratihb   : !pos 75.225 -6.000 -137.203 50\n-- Cutter   : !pos -462 -2 -394 54\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.AGAINST_ALL_ODDS)\n\nquest.reward =\n{\n    item  = xi.item.CORSAIRS_TRICORNE,\n    title = xi.title.PARAGON_OF_CORSAIR_EXCELLENCE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.NAVIGATING_THE_UNFRIENDLY_SEAS) == xi.questStatus.QUEST_COMPLETED and\n                player:getMainJob() == xi.job.COR and\n                player:getMainLvl() >= xi.settings.main.AF3_QUEST_LEVEL\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            onTriggerAreaEnter =\n            {\n                [5] = function(player, region)\n                    return quest:progressEvent(797)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [797] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LIFE_FLOAT)\n                    quest:setVar(player, 'Wait', JstMidnight())\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ratihb'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        not player:hasKeyItem(xi.keyItem.LIFE_FLOAT) and\n                        (\n                            quest:getVar(player, 'Wait') < GetSystemTime() or\n                            quest:getVar(player, 'Wait') == 0\n                        )\n                    then\n                        return quest:progressEvent(798)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [798] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LIFE_FLOAT)\n                    quest:setVar(player, 'Wait', JstMidnight())\n                end,\n            },\n        },\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['Cutter'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(238)\n                    end\n                end,\n            },\n\n            onTriggerAreaEnter =\n            {\n                [1] = function(player, region)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(237)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.THE_ASHU_TALIF and\n                    quest:getVar(player, 'Prog') == 2\n                then\n                    return 238\n                end\n            end,\n\n            onEventFinish =\n            {\n                [237] = function(player, csid, option, npc)\n                    player:startEvent(240)\n                end,\n\n                [238] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n\n                [240] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/COR_LB_Breaking_the_Bonds_of_Fate.lua"]={["Path"]="scripts/quests/ahtUrhgan/COR_LB_Breaking_the_Bonds_of_Fate.lua",["SHA256"]="5edc949171088f975cc2d3c37c9f3479b78f9e24d5a24c8d1fb6f499ee39568d",["Text"]="-----------------------------------\n-- Breaking the Bonds of Fate\n-- Corsair Limit Break Quest\n-----------------------------------\n-- Log ID: 6, Quest ID: 41\n-- qm6 (H-10/Boat)  : !pos 468.767 -12.292 111.817 54\n-----------------------------------\nlocal arrapagoID    = zones[xi.zone.ARRAPAGO_REEF]\nlocal talaccaCoveID = zones[xi.zone.TALACCA_COVE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.BREAKING_THE_BONDS_OF_FATE)\n\nquest.reward =\n{\n    title = xi.title.MASTER_OF_CHANCE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.AGAINST_ALL_ODDS) and\n                player:getMainJob() == xi.job.COR and\n                player:getMainLvl() >= 66\n        end,\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['qm6'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(234)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [234] = function(player, csid, option, npc)\n                    if option == 0 then\n                        return quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:getMainJob() == xi.job.COR and\n                player:getMainLvl() >= 66\n        end,\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['qm6'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if trade:getItemQty(xi.item.CORSAIRS_TESTIMONY) > 0 then\n                        return quest:progressEvent(235, { [7] = 1 })\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:messageSpecial(arrapagoID.text.YOU_MUST_BRING, xi.item.CORSAIRS_TESTIMONY)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [235] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                        player:setPos(-100.166, -7.701, -091.059, 197, xi.zone.TALACCA_COVE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.TALACCA_COVE] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.BREAKING_THE_BONDS_OF_FATE then\n                        if player:getLevelCap() == 70 then\n                            player:setLevelCap(75)\n                            player:messageSpecial(talaccaCoveID.text.YOUR_LEVEL_LIMIT_IS_NOW_75)\n                        end\n\n                        npcUtil.giveItem(player, { xi.item.SCROLL_OF_INSTANT_WARP })\n                        quest:complete(player)\n                    end\n                end,\n            },\n        },\n\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Cook-a-roon.lua"]={["Path"]="scripts/quests/ahtUrhgan/Cook-a-roon.lua",["SHA256"]="02f8765ae2fb558fc7cc23f560fbc2c553e2b4ebb83edd3407d6f62a7df6cfef",["Text"]="-----------------------------------\n-- Cook-a-roon\n-- Ququroon !pos -2.400 -1 66.824 53\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.COOK_A_ROON)\n\nquest.sections =\n{\n    -- Setion: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Ququroon'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(241)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [241] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Ququroon'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(242)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.AHTAPOT, xi.item.ISTAKOZ, xi.item.ISTAVRIT_1, xi.item.ISTIRIDYE, xi.item.MERCANBALIGI }) then\n                        quest:setVar(player, 'Prog', math.randomInt(2, 3))\n                        return quest:progressEvent(243, { [7] = quest:getVar(player, 'Prog') })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [243] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        npcUtil.giveItem(player, xi.item.BOWL_OF_NASHMAU_STEW)\n                    end\n\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest complete\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Ququroon'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.AHTAPOT, xi.item.ISTAKOZ, xi.item.ISTAVRIT_1, xi.item.ISTIRIDYE, xi.item.MERCANBALIGI }) then\n                        quest:setVar(player, 'Prog', math.randomInt(2, 3))\n                        return quest:progressEvent(243, { [7] = quest:getVar(player, 'Prog') })\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(244)\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [243] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    if quest:getVar(player, 'Prog') == 2 then\n                        npcUtil.giveItem(player, xi.item.BOWL_OF_NASHMAU_STEW)\n                    end\n\n                    quest:setVar(player, 'Prog', 0)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Delivering_the_Goods.lua"]={["Path"]="scripts/quests/ahtUrhgan/Delivering_the_Goods.lua",["SHA256"]="776bd42fa25360778b08897c66567d2b90542b4fa8dd850ea459d83edfb05071",["Text"]="-----------------------------------\n-- Delivering the Goods\n-- Fochacha, Whitegate , !pos 3 -1 -10.781 50\n-- Qutiba, Whitegate, !pos 92 -7.5 -130 50\n-- Ulamaal, Whitegate, !pos 93 -7.5 -128 50\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.DELIVERING_THE_GOODS)\n\nquest.reward =\n{\n    item = { { xi.item.IMPERIAL_BRONZE_PIECE, 3 } }\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fochacha'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(39)\n                end,\n            },\n            ['Qutiba'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(51)\n                end,\n            },\n            ['Ulamaal'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(51)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [39] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fochacha'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(46)\n                end,\n            },\n            ['Qutiba'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(40)\n                end,\n            },\n            ['Ulamaal'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(40)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [40] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Section: Complete quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fochacha'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(41)\n                end,\n            },\n            ['Qutiba'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(52)\n                end,\n            },\n            ['Ulamaal'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(53)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [41] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.VANISHING_ACT, 'Stage', GetSystemTime() + 60) -- 1 minute wait time\n\n                        -- Player must zone before being able to flag the next quest\n                        -- Capture: retail still refused two minutes after the turn in. The timer alone does not open it.\n                        player:needToZone(true)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Divine_Interference.lua"]={["Path"]="scripts/quests/ahtUrhgan/Divine_Interference.lua",["SHA256"]="fbe0833efb766141ef523344596a1a98e9d3b65062d10a8a4a8426014d4b160c",["Text"]="-----------------------------------\n-- Divine Interference\n-----------------------------------\n-- Log ID: 6, Quest ID: 75\n-- Naja Salaheem, !pos 22.700 -8.804 -45.591 50\n-- Imperial Whitegate, !pos 152.8295 -2.2 0.0613 50\n-- Acid-Eaten Door, !pos 271.9045 -32 -88 61\n-- Blank Lamp, !pos 209.3953 0.05 20.0207 72\n-- Runic Seal, !pos 125.4569 0 19.9914 72\n-- Naja Salaheem, !pos 22.700 -8.804 -45.591 50\n-----------------------------------\nlocal ahtUrhganID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.DIVINE_INTERFERENCE)\n\nquest.reward =\n{\n    title = xi.title.HEIR_OF_THE_BLESSED_RADIANCE,\n    item  = { xi.item.IMPERIAL_GOLD_PIECE }\n}\n\nlocal rewardItems =\n{\n    [0] = xi.item.COLOSSUSS_MANTLE,\n    [1] = xi.item.COLOSSUSS_EARRING,\n    [2] = xi.item.COLOSSUSS_TORQUE,\n}\n\nlocal function getRewardMask(player)\n    local rewardMask = 0\n\n    for bitNum, itemId in pairs(rewardItems) do\n        if player:hasItem(itemId) then\n            rewardMask = utils.mask.setBit(rewardMask, bitNum, true)\n        end\n    end\n\n    if player:hasSpell(xi.magic.spell.ALEXANDER) then\n        rewardMask = utils.mask.setBit(rewardMask, 4, true)\n    end\n\n    return rewardMask\nend\n\nlocal function giveQuestReward(player, eventOption)\n    local wasRewarded = true\n\n    if eventOption <= 3 then\n        wasRewarded = npcUtil.giveItem(player, rewardItems[eventOption - 1])\n    elseif eventOption == 4 then\n        npcUtil.giveCurrency(player, 'gil', 10000)\n    elseif eventOption == 5 then\n        player:addSpell(xi.magic.spell.ALEXANDER)\n        player:messageSpecial(ahtUrhganID.text.ALEXANDER_UNLOCKED, 0, 0, 1)\n    end\n\n    return wasRewarded\nend\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            if\n                status == xi.questStatus.QUEST_AVAILABLE and\n                player:getCurrentMission(xi.mission.log_id.TOAU) == xi.mission.id.toau.ETERNAL_MERCENARY and\n                player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.WAKING_THE_COLOSSUS) and\n                quest:getVar(player, 'Timer') == 0\n            then\n                return true\n            end\n\n            return false\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Imperial_Whitegate'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(931, { text_table = 0 })\n                    end\n                end,\n            },\n\n            onTriggerAreaEnter =\n            {\n                [13] = function(player, triggerArea)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(930, { text_table = 0, [0] = xi.besieged.getMercenaryRank(player), [1] = 1 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [930] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [931] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ALZADAAL_UNDERSEA_RUINS] =\n        {\n            ['blank_lamp'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        player:hasKeyItem(xi.keyItem.LIGHTNING_CELL)\n                    then\n                        return quest:progressEvent(308)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if\n                    quest:getVar(player, 'Prog') == 4 and\n                    not player:hasKeyItem(xi.keyItem.WHISPER_OF_RADIANCE)\n                then\n                    return 309\n                end\n            end,\n\n            onEventFinish =\n            {\n                [308] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [309] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.WHISPER_OF_RADIANCE)\n                end,\n            },\n        },\n\n        [xi.zone.MOUNT_ZHAYOLM] =\n        {\n            ['Acid-eaten_Door'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(157)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') >= 2 and\n                        npcUtil.tradeHasExactly(trade, { { xi.item.SLAB_OF_PLUMBAGO, 3 } }) and\n                        not player:hasKeyItem(xi.keyItem.LIGHTNING_CELL)\n                    then\n                        return quest:progressEvent(158)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [157] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [158] = function(player, csid, option, npc)\n                    if npcUtil.giveKeyItem(player, xi.keyItem.LIGHTNING_CELL) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        }\n    },\n\n    -- Section: Complete quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:hasKeyItem(xi.keyItem.WHISPER_OF_RADIANCE)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(932, { text_table = 0, [0] = xi.besieged.getMercenaryRank(player), [7] = getRewardMask(player) })\n                end,\n            },\n\n            onEventFinish =\n            {\n                [932] = function(player, csid, option, npc)\n                    if giveQuestReward(player, option) then\n                        quest:complete(player)\n                        player:delKeyItem(xi.keyItem.WHISPER_OF_RADIANCE)\n                        quest:setTimedVar(player, 'Timer', NextJstDay())\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Repeat quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and quest:getVar(player, 'Timer') == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Imperial_Whitegate'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(931, { text_table = 0 })\n                end,\n            },\n\n            onEventFinish =\n            {\n                [931] = function(player, csid, option, npc)\n                    player:delQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.DIVINE_INTERFERENCE)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Embers_of_His_Past.lua"]={["Path"]="scripts/quests/ahtUrhgan/Embers_of_His_Past.lua",["SHA256"]="58b4ed5654bd7d235feb9d9d33c2daf0c03ce0b491ec7cad2e1bde6dd5ba4f4a",["Text"]="-----------------------------------\n-- Embers of His Past\n-- Logid: 6 Questid: 48\n-- Fari-Wari          : !pos 80 -6 -137 50\n-- Sprightly Footsteps: !pos 822 -18 176 61\n-- Withered Petals    : !pos 857 -14 248 61\n-----------------------------------\nlocal wajaomID  = zones[xi.zone.WAJAOM_WOODLANDS]\nlocal whitegateID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.EMBERS_OF_HIS_PAST)\n\nquest.reward =\n{\n    item  = xi.item.IMPERIAL_GOLD_PIECE,\n    title = xi.title.FLAMESERPENT_FACILITATOR\n}\n\nquest.sections =\n{\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.SOOTHING_WATERS) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:progressEvent(916, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [916] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    quest:begin(player)\n                    player:setPos(0, 0, 0, 0, xi.zone.WAJAOM_WOODLANDS)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 1\n        end,\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 16\n            end,\n\n            onEventFinish =\n            {\n                [16] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:setPos(0, 0, 0, 0, xi.zone.WAJAOM_WOODLANDS)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 2\n        end,\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 17\n            end,\n\n            onEventFinish =\n            {\n                [17] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    player:setPos(80, -6, -123, 55, xi.zone.AHT_URHGAN_WHITEGATE)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 3\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:event(917),\n        },\n\n        [xi.zone.MOUNT_ZHAYOLM] =\n        {\n            ['Sprightly_Footsteps'] =\n            {\n                onTrigger = function(player, npc)\n                    if VanadielHour() >= 18 or VanadielHour() <= 6 then\n                        return quest:progressCutscene(15)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [15] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 4\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:event(917),\n        },\n\n        [xi.zone.MOUNT_ZHAYOLM] =\n        {\n            ['Withered_Petals'] =\n            {\n                onTrigger = function(player, npc)\n                    if VanadielHour() >= 18 or VanadielHour() <= 6 then\n                        return quest:progressCutscene(16)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [16] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                    player:setPos(141.740, -2, 0, 132, xi.zone.AHT_URHGAN_WHITEGATE)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 5\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.HYDRANGEA) then\n                        return quest:progressEvent(918, { text_table = 0 })\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(924)\n                end,\n            },\n            onEventFinish =\n            {\n                [918] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                    player:setPos(0, 0, 0, 0, xi.zone.WAJAOM_WOODLANDS)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 6\n        end,\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 18\n            end,\n\n            onEventFinish =\n            {\n                [18] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 7)\n                    player:setPos(0, 0, 0, 0, xi.zone.WAJAOM_WOODLANDS)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 7\n        end,\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 19\n            end,\n\n            onEventFinish =\n            {\n                [19] = function(player, csid, option, npc)\n                    player:messageSpecial(wajaomID.text.ITEM_RETURNED, xi.item.HYDRANGEA)\n                    quest:setVar(player, 'Prog', 8)\n                    player:timer(1000, function(playerArg)\n                        playerArg:setPos(80, -6, -123, 55, xi.zone.AHT_URHGAN_WHITEGATE)\n                    end)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 8\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:event(919),\n        },\n\n        [xi.zone.MOUNT_ZHAYOLM] =\n        {\n            ['Withered_Petals'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if VanadielHour() >= 18 or VanadielHour() <= 6 then\n                        if npcUtil.tradeHasExactly(trade, xi.item.HYDRANGEA) then\n                            return quest:progressCutscene(17)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [17] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:startCutscene(18)\n                end,\n\n                [18] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 9)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 9\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:progressEvent(920, { text_table = 0 }),\n\n            onEventFinish =\n            {\n                [920] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addCurrency('imperial_standing', 500)\n                        player:messageSpecial(whitegateID.text.BESIEGED_OFFSET)\n                        player:needToZone(true)\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n            not player:needToZone()\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        return quest:progressEvent(921, { text_table = 0 })\n                    else\n                        return quest:event(923, { text_table = 0 }):replaceDefault()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [921] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.MERCENARY_CAMP_ENTRY_SLIP) then\n                        quest:setVar(player, 'Option', 0)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Fear_of_the_Dark_2.lua"]={["Path"]="scripts/quests/ahtUrhgan/Fear_of_the_Dark_2.lua",["SHA256"]="e1a70c8f41c885c831c58b06cd606bc6a26582cc9ec414c32614dd480c12a017",["Text"]="-----------------------------------\n-- Fear of the Dark 2\n-- Suldiran !pos 42 -7 -43 48\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.FEAR_OF_THE_DARK_II)\n\nquest.reward =\n{\n    gil = 200,\n    title = xi.title.DARK_RESISTANT,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AL_ZAHBI] =\n        {\n            ['Suldiran'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(14)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [14] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AL_ZAHBI] =\n        {\n            ['Suldiran'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(15)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.IMP_WING, 2 } }) then\n                        return quest:progressEvent(16)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [16] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AL_ZAHBI] =\n        {\n            ['Suldiran'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(17)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.IMP_WING, 2 } }) then\n                        return quest:progressEvent(18)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [18] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveCurrency(player, 'gil', 200)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Fist_of_the_People.lua"]={["Path"]="scripts/quests/ahtUrhgan/Fist_of_the_People.lua",["SHA256"]="e1b7e2661aa3bd6d9b88c308b4630eed5293a470c2ba0c1347734f48a97178e4",["Text"]="-----------------------------------\n-- Fist of the People\n-----------------------------------\n-- Log ID: 6, Quest ID: 46\n-- Talhaal  : !pos -36 -6 107 48\n-- Fari-Wari: !pos 80 -6 -137 50\n-- Leypoint : !pos -200 -10 80 51\n-----------------------------------\nlocal ID = zones[xi.zone.WAJAOM_WOODLANDS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.FIST_OF_THE_PEOPLE)\n\nquest.reward =\n{\n    title = xi.title.STONESERPENT_SHOCKTROOPER,\n}\n\nquest.sections =\n{\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.ODE_TO_THE_SERPENTS) == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AL_ZAHBI] =\n        {\n            ['Talhaal'] = quest:progressEvent(282),\n\n            onEventFinish =\n            {\n                [282] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:progressEvent(884),\n\n            onEventFinish =\n            {\n                [884] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            ['Leypoint'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.RUSTY_MEDAL) then\n                        return quest:progressEvent(511)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [511] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:messageSpecial(ID.text.INCREASED_STANDING)\n                        player:addCurrency('imperial_standing', 500)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Give_Peace_a_Chance.lua"]={["Path"]="scripts/quests/ahtUrhgan/Give_Peace_a_Chance.lua",["SHA256"]="ae4b64c65c3c9534bc128546fda5550580e6cc9abefa0a66730b70d77384af46",["Text"]="-----------------------------------\n-- Give Peace a Chance\n-- Mishhar, Whitegate , !pos -12 -6 29 50\n-- QM8, Wajaom Woodlands, !pos 416 -24 220 51\n-- QM4, Mamook, !pos 347 -12 -256 65\n-----------------------------------\n-- require('cripts/globals/weather')\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.GIVE_PEACE_A_CHANCE)\n\nquest.reward =\n{\n    item = xi.item.IMPERIAL_SILVER_PIECE,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Mishhar'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(562)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [562] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Mishhar'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    if questProgress == 0 then\n                        return quest:event(587)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(575)\n                    elseif questProgress == 2 then\n                        return quest:event(588)\n                    elseif questProgress == 3 then\n                        return quest:progressEvent(576)\n                    elseif questProgress == 4 then\n                        return quest:progressEvent(589)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [575] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [576] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:needToZone(true)\n                        player:setVar('Quest[6][30]Stage', JstMidnight())\n                    else\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n\n                [589] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:needToZone(true)\n                        player:setVar('Quest[6][30]Stage', JstMidnight())\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            ['qm8'] =\n            {\n                onTrigger = function(player, npc)\n                    if VanadielTOTD() == xi.time.NIGHT and quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressCutscene(504)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [504] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.MAMOOK] =\n        {\n            ['qm4'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressCutscene(211)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [211] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Got_It_All.lua"]={["Path"]="scripts/quests/ahtUrhgan/Got_It_All.lua",["SHA256"]="a093d41069f65d5d9eddd889801b3b4c186581e78a4f1bf84148c491d3c7ae98",["Text"]="-----------------------------------\n-- Got It All\n-- Tehf Kimasnahya !pos -89.897 -1 6.199 50\n-- Ekhu Pesshyadha !pos -13.043 0.999 103.423 50\n-- Zabahf !pos -90.070 -1 10.140 50\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.GOT_IT_ALL)\n\nquest.reward =\n{\n    item = xi.item.BIBIKI_SEASHELL,\n}\n\nquest.sections =\n{\n    -- Section: Begin quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Tehf_Kimasnahya'] = quest:progressEvent(520),\n            ['Ekhu_Pesshyadha'] = quest:event(532),\n            ['Zabahf'] = quest:event(533),\n\n            onEventFinish =\n            {\n                [520] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Section: Questing\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Tehf_Kimasnahya'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress < 4 then\n                        return quest:event(521)\n                    elseif progress == 4 then\n                        return quest:progressEvent(525)\n                    elseif progress == 5 then\n                        return quest:event(534)\n                    elseif progress == 6 then\n                        return quest:progressEvent(527)\n                    elseif progress == 7 then\n                        if not player:needToZone() then\n                            return quest:progressEvent(528)\n                        else\n                            return quest:event(539)\n                        end\n                    end\n                end,\n            },\n\n            ['Ekhu_Pesshyadha'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 1 then\n                        return quest:progressEvent(522)\n                    elseif progress == 2 then\n                        return quest:event(536)\n                    elseif progress == 3 then\n                        return quest:progressEvent(524)\n                    elseif progress >= 4 then\n                        return quest:event(537)\n                    end\n                end,\n            },\n\n            ['Zabahf'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if\n                        progress == 2 or\n                        progress == 3\n                    then\n                        return quest:progressEvent(523)\n                    elseif progress == 5 then\n                        return quest:event(538)\n                    elseif progress == 6 then\n                        return quest:event(540)\n                    elseif progress == 7 then\n                        return quest:event(535)\n                    else\n                        return quest:event(533)\n                    end\n                end,\n            },\n\n            onTriggerAreaEnter =\n            {\n                [1] = function(player, triggerArea)\n                    if quest:getVar(player, 'Prog') == 5 then\n                        return quest:progressEvent(526)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [522] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [523] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [524] = function(player, csid, option, npc)\n                    if npcUtil.giveKeyItem(player, xi.keyItem.VIAL_OF_LUMINOUS_WATER) then\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n\n                [525] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 5)\n                        player:delKeyItem(xi.keyItem.VIAL_OF_LUMINOUS_WATER)\n                    end\n                end,\n\n                [526] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n\n                [527] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 7)\n                    player:needToZone(true)\n                end,\n\n                [528] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: After completion\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ekhu_Pesshyadha'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THREE_MEN_AND_A_CLOSET) ~= xi.questStatus.QUEST_COMPLETED then\n                        return quest:event(531)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Keeping_Notes.lua"]={["Path"]="scripts/quests/ahtUrhgan/Keeping_Notes.lua",["SHA256"]="3c0e0fb8eafc34a91bf8edfccf0cc79b842b374aa1baa42b13e39bc4e368784a",["Text"]="-----------------------------------\n-- Keeping Notes\n-- Ahkk Jharcham, Whitegate , !pos 0.1 -1 -76 50\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.KEEPING_NOTES)\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ahkk_Jharcham'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(9)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [9] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ahkk_Jharcham'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(10)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.SHEET_OF_PARCHMENT, xi.item.JAR_OF_BLACK_INK }) then\n                        return quest:progressEvent(11)\n                    else\n                        return quest:event(14)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [11] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        local mhflag = player:getMoghouseFlag()\n                        player:setMoghouseFlag(mhflag + 0x0010)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ahkk_Jharcham'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(12)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.SHEET_OF_PARCHMENT) then\n                        return quest:event(13)\n                    else\n                        return quest:event(14)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Led_Astray.lua"]={["Path"]="scripts/quests/ahtUrhgan/Led_Astray.lua",["SHA256"]="bf797d4cde9027152457eb4afae60c4e4f82937fa4aaababb67b209ac8884fe2",["Text"]="-----------------------------------\n-- Led Astry\n-- Log: 6, Quest: 65\n-- Mhasbaf:         !pos 54.701 -6.999 11.387 50\n-- Whitegate Region !pos 71 0 9.299 50\n-- Tohka Telposkha: !pos 22.1 0 22.759 50\n-- Rubahah:         !pos -96.746 0 -14.701 50\n-- Cacaroon:        !pos -72.026 0.000 -82.337 50\n-- Whitegate Region !pos 12.5 -94 2 50\n-- Tataroon:        !pos -25.189 0 -39.022 53\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.LED_ASTRAY)\n\nquest.reward =\n{\n    item = xi.item.IMPERIAL_SILVER_PIECE,\n}\n\nquest.sections =\n{\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Mhasbaf'] = quest:progressEvent(808),\n\n            onEventFinish =\n            {\n                [808] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Mhasbaf'] = quest:event(834):oncePerZone(),\n\n            onTriggerAreaEnter =\n            {\n                [7] = function(player, triggerArea)\n                    return quest:progressEvent(809)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [809] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Mhasbaf'] = quest:event(834):oncePerZone(),\n\n            ['Tohka_Telposkha'] = quest:progressEvent(810),\n\n            onEventFinish =\n            {\n                [810] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Mhasbaf'] = quest:event(834):oncePerZone(),\n\n            ['Rubahah'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Stage', 1) then\n                        return quest:progressEvent(811)\n                    end\n                end,\n            },\n\n            ['Cacaroon'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Stage', 2) then\n                        return quest:progressEvent(812)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [811] = function(player, csid, option, npc)\n                    if quest:isVarBitsSet(player, 'Stage', 2) then\n                        quest:setVar(player, 'Prog', 3)\n                        quest:setVar(player, 'Stage', 0)\n                    else\n                        quest:setVarBit(player, 'Stage', 1)\n                    end\n                end,\n\n                [812] = function(player, csid, option, npc)\n                    if quest:isVarBitsSet(player, 'Stage', 1) then\n                        quest:setVar(player, 'Prog', 3)\n                        quest:setVar(player, 'Stage', 0)\n                    else\n                        quest:setVarBit(player, 'Stage', 2)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Mhasbaf'] = quest:event(834),\n\n            onTriggerAreaEnter =\n            {\n                [8] = function(player, triggerArea)\n                    return quest:progressEvent(813)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [813] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_BERNAHN)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 4\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Mhasbaf'] = quest:event(834):oncePerZone(),\n        },\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Tataroon'] = quest:progressEvent(305),\n\n            onEventFinish =\n            {\n                [305] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.LETTER_FROM_BERNAHN)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Luck_of_the_Draw.lua"]={["Path"]="scripts/quests/ahtUrhgan/Luck_of_the_Draw.lua",["SHA256"]="bde43596f99f9bf044a46fd77162c5c310b736b902a08dd793bf76496914eb88",["Text"]="-----------------------------------\n-- Luck of the Draw\n-- Corsair Job Flag Quest\n-----------------------------------\n-- Log ID: 6, Quest ID: 6\n-- Ratihb           : !pos 75.225 -6.000 -137.203 50\n-- Mafwahb          : !pos 149.11 -2.000 -2.7127 50\n-- qm6 (H-10 / Boat): !pos 468.767 -12.292 111.817 54\n-- qm1              : !pos -62.239 -7.9619 -137.1251\n-- _1l0 (Rock Slab) : !pos -99 -7 -91 57\n-----------------------------------\nlocal talaccaCoveID = zones[xi.zone.TALACCA_COVE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.LUCK_OF_THE_DRAW)\n\nquest.reward =\n{\n    item    = xi.item.CORSAIR_DIE,\n    keyItem = xi.keyItem.JOB_GESTURE_CORSAIR,\n    title   = xi.title.SEAGULL_PHRATRIE_CREW_MEMBER,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ratihb'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(547)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [547] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Mafwahb'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(548)\n                    elseif questProgress == 2 then\n                        return quest:event(647)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [548] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['qm6'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressCutscene(211)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [211] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.TALACCA_COVE] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(2)\n                    end\n                end,\n            },\n\n            ['_1l0'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(3)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                    npcUtil.giveKeyItem(player, xi.keyItem.FORGOTTEN_HEXAGUN)\n                end,\n\n                [3] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.FORGOTTEN_HEXAGUN)\n                        player:unlockJob(xi.job.COR)\n                        player:messageSpecial(talaccaCoveID.text.YOU_CAN_NOW_BECOME_A_CORSAIR)\n                    end\n                end,\n            },\n        }\n    },\n\n    -- Section: Quest complete.\n    {\n        check = function(player, status, vars)\n            -- Event 552 is a one-time-only event that can occur after completing \"Luck of the Draw\"\n            -- but before finishing Equipped for all Occasions.\n            -- This charvar is cleaned up on complete of 'Equipped for all Occasions' when quest:complete() is called.\n\n            return status == xi.questStatus.QUEST_COMPLETED and\n                xi.quest.getVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.EQUIPPED_FOR_ALL_OCCASIONS, 'Stage') == 0 and\n                not player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.EQUIPPED_FOR_ALL_OCCASIONS)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Ratihb'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(552)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [552] = function(player, csid, option, npc)\n                    xi.quest.setVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.EQUIPPED_FOR_ALL_OCCASIONS, 'Stage', 1)\n                end,\n            },\n        },\n    }\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Moment_of_Truth.lua"]={["Path"]="scripts/quests/ahtUrhgan/Moment_of_Truth.lua",["SHA256"]="25c8f1aea3e4687e1dd124c85b1fa824dc09cbc8f8df78a11c591ae3f00c1bc3",["Text"]="-----------------------------------\n-- Moment of Truth: Quest 6 30\n-- Mishhar, Whitegate , !pos -12 -6 29 50\n-- QM7, Mamook, !pos 216.861,-26.141,-94.554 65\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.MOMENT_OF_TRUTH)\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.GIVE_PEACE_A_CHANCE) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Mishhar'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(800)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [800] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Mishhar'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    if questProgress == 0 then\n                        return quest:event(801)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(803)\n                    elseif questProgress == 2 then\n                        return quest:event(588)\n                    elseif\n                        questProgress == 3 or\n                        questProgress == 4\n                    then\n                        return quest:event(804)\n                    elseif questProgress == 5 then\n                        return quest:progressEvent(805)\n                    end\n                end,\n            },\n\n            onTriggerAreaEnter =\n            {\n                [5] = function(player, region)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(802)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [802] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [803] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [805] = function(player, csid, option, npc)\n                    local jobRewardItems =\n                    {\n                        [xi.job.WAR] = xi.item.STRENGTH_POTION,\n                        [xi.job.MNK] = xi.item.STRENGTH_POTION,\n                        [xi.job.DRK] = xi.item.STRENGTH_POTION,\n                        [xi.job.DRG] = xi.item.STRENGTH_POTION,\n\n                        [xi.job.WHM] = xi.item.MIND_POTION,\n\n                        [xi.job.BLM] = xi.item.INTELLIGENCE_POTION,\n                        [xi.job.SCH] = xi.item.INTELLIGENCE_POTION,\n\n                        [xi.job.RDM] = xi.item.VILE_ELIXIR_P1,\n                        [xi.job.BLU] = xi.item.VILE_ELIXIR_P1,\n\n                        [xi.job.THF] = xi.item.HERMES_QUENCHER,\n                        [xi.job.PLD] = xi.item.VITALITY_POTION,\n\n                        [xi.job.BST] = xi.item.CHARISMA_POTION,\n                        [xi.job.BRD] = xi.item.CHARISMA_POTION,\n                        [xi.job.DNC] = xi.item.CHARISMA_POTION,\n\n                        [xi.job.RNG] = xi.item.AGILITY_POTION,\n                        [xi.job.NIN] = xi.item.AGILITY_POTION,\n                        [xi.job.COR] = xi.item.AGILITY_POTION,\n\n                        [xi.job.SAM] = xi.item.ICARUS_WING,\n                        [xi.job.SMN] = xi.item.PRO_ETHER_P1,\n                        [xi.job.PUP] = xi.item.DEXTERITY_POTION,\n                    }\n\n                    local playerjob = player:getMainJob()\n                    local rewardItem = jobRewardItems[playerjob]\n\n                    if npcUtil.giveItem(player, rewardItem) then\n                        quest:complete(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.MAMOOK] =\n        {\n            ['qm7'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressCutscene(221)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [221] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.JADE_SEPULCHER] =\n        {\n            ['_1v0'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(3)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.MOMENT_OF_TRUTH then\n                        quest:setVar(player, 'Prog', 5)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Mishhar'] = quest:event(806):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/No_Strings_Attached.lua"]={["Path"]="scripts/quests/ahtUrhgan/No_Strings_Attached.lua",["SHA256"]="09abb698bf0889e119c52124a1da4c0bdd68ef87907dd8c7a41362586f24b831",["Text"]="-----------------------------------\n-- No Strings Attached\n-----------------------------------\n-- Log ID: 6, Quest ID: 7\n-- Shamarhaan   : !pos -285.382 -13.021 -84.743 235\n-- Iruki-Waraki : !pos 101.329 -6.999 -29.042 50\n-- Ghatsad      : !pos 34.325 -7.804 57.511 50\n-- qm10         : !pos 457.128 -8.249 60.795 54\n-----------------------------------\nlocal ahtUrhganID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\nlocal arrapagoID  = zones[xi.zone.ARRAPAGO_REEF]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.NO_STRINGS_ATTACHED)\n\nquest.reward =\n{\n    item    = xi.item.ANIMATOR,\n    keyItem = xi.keyItem.JOB_GESTURE_PUPPETMASTER,\n    title   = xi.title.PROUD_AUTOMATON_OWNER,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Shamarhaan'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 0 then\n                        return quest:progressEvent(434) -- This CS appears to be bugged on retail and no longer plays\n                    else\n                        return quest:event(435)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [434] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n            },\n        },\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Iruki-Waraki'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        return quest:progressEvent(260)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [260] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest Accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Shamarhaan'] = quest:event(435)\n        },\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Iruki-Waraki'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress <= 3 then\n                        return quest:event(261)\n                    elseif questProgress == 4 then\n                        return quest:progressEvent(266)\n                    end\n                end,\n            },\n\n            ['Ghatsad'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(262)\n                    elseif questProgress == 1 then\n                        return quest:event(263):oncePerZone()\n                    elseif\n                        questProgress == 2 and\n                        player:hasKeyItem(xi.keyItem.ANTIQUE_AUTOMATON)\n                    then\n                        return quest:progressEvent(264)\n                    elseif\n                        questProgress == 3 and\n                        quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n                    then\n                        return quest:progressEvent(265)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [262] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [264] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                    player:delKeyItem(xi.keyItem.ANTIQUE_AUTOMATON)\n                end,\n\n                [265] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [266] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:unlockJob(xi.job.PUP)\n                        player:messageSpecial(ahtUrhganID.text.YOU_CAN_BECOME_PUP)\n                        player:setPetName(xi.petType.AUTOMATON, option + 118)\n                        player:unlockAttachment(xi.item.HARLEQUIN_FRAME)\n                        player:unlockAttachment(xi.item.HARLEQUIN_HEAD)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.ARRAPAGO_REEF] =\n        {\n            ['qm10'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressCutscene(214)\n                    else\n                        return quest:messageSpecial(arrapagoID.text.PILE_OF_DISCARDED_MATERIALS)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [214] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.ANTIQUE_AUTOMATON)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest Completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Iruki-Waraki'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:findItem(xi.item.ANIMATOR) and\n                        npcUtil.tradeHas(trade, { { 'gil', 10000 } })\n                    then\n                        player:confirmTrade()\n                        npcUtil.giveItem(player, xi.item.ANIMATOR)\n                        return quest:messageName(ahtUrhganID.text.YOU_BETTER_NOT_LOSE_IT_AGAIN, 0, 0, 0, 0, true, false)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if not player:findItem(xi.item.ANIMATOR) then\n                        return quest:messageName(ahtUrhganID.text.YOU_LOST_YOUR_ANIMATOR, xi.item.ANIMATOR, 0, 0, 0, true, false)\n                    else\n                        return quest:event(267)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Not_Meant_to_Be.lua"]={["Path"]="scripts/quests/ahtUrhgan/Not_Meant_to_Be.lua",["SHA256"]="eb7f4a6e9d9421de104fa9543cf210b56abf2e2c50ce6820fd416051903652cb",["Text"]="-----------------------------------\n-- Not Meant to Be\n-----------------------------------\n-- Log ID: 6, Quest ID: 64\n-- Fhe Maksojha   : !pos 19.084 -7 71.287 53\n-- qm12 (Caedarva): !pos 456.993 -7.000 -270.815 79\n-----------------------------------\nlocal caedarvaMireID = zones[xi.zone.CAEDARVA_MIRE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.NOT_MEANT_TO_BE)\n\nquest.reward =\n{\n    item =\n    {\n        { xi.item.IMPERIAL_GOLD_PIECE, 3 },\n    },\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Fhe_Maksojha'] =\n            {\n                onTrigger = quest:progressEvent(293),\n            },\n\n            onEventFinish =\n            {\n                [293] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Fhe_Maksojha'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:event(295)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(294)\n                    elseif questProgress == 3 then\n                        return quest:event(296)\n                    elseif questProgress == 4 then\n                        return quest:event(297)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [294] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [297] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.CAEDARVA_MIRE] =\n        {\n            ['qm12'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    local questStage = quest:getVar(player, 'Stage')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(16)\n                    elseif questProgress == 3 then\n                        if\n                            questStage < 3 and\n                            not GetMobByID(caedarvaMireID.mob.LAMIA_NO27):isSpawned() and\n                            not GetMobByID(caedarvaMireID.mob.MOSHDAHN):isSpawned()\n                        then\n                            return quest:event(17)\n                        elseif questStage == 3 then\n                            return quest:progressEvent(18)\n                        end\n                    end\n                end,\n            },\n\n            ['Lamia_No27'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        quest:setVarBit(player, 'Stage', 0)\n                    end\n                end,\n            },\n\n            ['Moshdahn'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        quest:setVarBit(player, 'Stage', 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [16] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [17] = function(player, csid, option, npc)\n                    -- This conditional exists in both the trigger and the event finish in the original implementation\n                    -- and left in as additional protection to prevent multiple sets of NMs being spawned if the ???\n                    -- is hit by multiple players at the same time.  This is a fairly long cutscene!\n                    if\n                        not GetMobByID(caedarvaMireID.mob.LAMIA_NO27):isSpawned() and\n                        not GetMobByID(caedarvaMireID.mob.MOSHDAHN):isSpawned()\n                    then\n                        SpawnMob(caedarvaMireID.mob.LAMIA_NO27):updateClaim(player)\n                        SpawnMob(caedarvaMireID.mob.MOSHDAHN):updateClaim(player)\n                    end\n                end,\n\n                [18] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        }\n    },\n\n    -- Section: Quest completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Fhe_Maksojha'] = quest:event(298)\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Ode_to_the_Serpents.lua"]={["Path"]="scripts/quests/ahtUrhgan/Ode_to_the_Serpents.lua",["SHA256"]="5d0beab85a587db7195399ebb10a8a9de04c7693f31aee5f2b8e3258fc036c01",["Text"]="-----------------------------------\n-- Ode to the Serpents\n-----------------------------------\n-- Log ID: 6, Quest ID: 44\n-- Fari-Wari: !pos 80 -6 -137 50\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.ODE_TO_THE_SERPENTS)\n\nquest.reward =\n{\n    item = xi.item.IMPERIAL_GOLD_PIECE,\n}\n\nquest.sections =\n{\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.SAGA_OF_THE_SKYSERPENT)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] = quest:progressEvent(882),\n\n            onEventFinish =\n            {\n                [882] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BIYAADAS_LETTER)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Fari-Wari'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.WHEN_THE_BOW_BREAKS) and\n                        player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.FIST_OF_THE_PEOPLE)\n                    then\n                        return quest:progressEvent(883)\n                    else\n                        return quest:event(891)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [883] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.BIYAADAS_LETTER)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/ahtUrhgan/Olduum.lua"]={["Path"]="scripts/quests/ahtUrhgan/Olduum.lua",["SHA256"]="dca84970a74d75dd9ca96da1ad931da4a6166dc0f6a89ac1e36c9a11ef89a8a0",["Text"]="-----------------------------------\n-- Olduum\n-- Dkhaaya !pos -73 -1 -6 50\n-- Excavation Site !pos 390 1 349 68\n-- Leypoint !pos -200 -8.5 80 51\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OLDUUM)\n\nquest.reward =\n{\n    item = xi.item.LIGHTNING_BAND,\n}\n\nlocal keyItems =\n{\n    xi.keyItem.ELECTROCELL,\n    xi.keyItem.ELECTROPOT,\n    xi.keyItem.ELECTROLOCOMOTIVE,\n}\n\nlocal function getQuestKeyItem(player)\n    for _, keyItem in ipairs(keyItems) do\n        if player:hasKeyItem(keyItem) then\n            return keyItem\n        end\n    end\n\n    return xi.keyItem.NONE\nend\n\nquest.sections =\n{\n    -- Section: Begin quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Dkhaaya'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(4)\n                end\n            },\n\n            onEventFinish =\n            {\n                [4] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.DKHAAYAS_RESEARCH_JOURNAL)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Dkhaaya'] =\n            {\n                onTrigger = function(player, npc)\n                    local questKeyItem = getQuestKeyItem(player)\n\n                    if questKeyItem > 0 then\n                        return quest:progressEvent(6, { [0] = questKeyItem })\n                    else\n                        return quest:event(5)\n                    end\n                end\n            },\n\n            onEventUpdate =\n            {\n                [6] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(keyItems[quest:getVar(player, 'Prog')])\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [6] = function(player, csid, option, npc)\n                    local cellKeyItem = keyItems[quest:getVar(player, 'Prog')]\n\n                    if quest:complete(player) then\n                        player:delKeyItem(cellKeyItem)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.AYDEEWA_SUBTERRANE] =\n        {\n            ['Excavation_Site'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:hasItem(xi.item.OLDUUM_RING) and\n                        getQuestKeyItem(player) == xi.keyItem.NONE and\n                        npcUtil.tradeMatches(trade, { { xi.item.PICKAXE, 1 } })\n                    then\n                        if math.randomInt(1, 100) <= 50 then\n                            quest:setVar(player, 'Prog', math.randomInt(1, 3))\n\n                            return quest:progressEvent(0, { [0] = keyItems[quest:getVar(player, 'Prog')] })\n                        else\n                            player:setLocalVar('mineFail', 1)\n                            return quest:progressEvent(0, { [1] = 1 })\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [0] = function(player, csid, option, npc)\n                    if player:getLocalVar('mineFail') == 1 then\n                        player:setLocalVar('mineFail', 0)\n                    else\n                        player:addKeyItem(keyItems[quest:getVar(player, 'Prog')])\n                    end\n\n                    player:tradeComplete()\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Dkhaaya'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasItem(xi.item.OLDUUM_RING) or\n                        player:hasItem(xi.item.LIGHTNING_BAND) or\n                        quest:getVar(player, 'Wait') > GetSystemTime()\n                    then\n                        return quest:progressEvent(7)\n                    end\n\n                    if quest:getVar(player, 'Reissue') == 1 then\n                        local questKeyItem = getQuestKeyItem(player)\n\n                        if questKeyItem > 0 then\n                            return quest:progressEvent(8, { [0] = questKeyItem })\n                        end\n\n                        return quest:progressEvent(7, { [7] = 2 })\n                    end\n\n                    return quest:progressEvent(7, { [7] = 1 })\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [8] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(keyItems[quest:getVar(player, 'Prog')])\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    if\n                        option ~= 99 or\n                        player:hasItem(xi.item.OLDUUM_RING) or\n                        player:hasItem(xi.item.LIGHTNING_BAND) or\n                        getQuestKeyItem(player) > 0 or\n                        quest:getVar(player, 'Wait') > GetSystemTime()\n                    then\n                        return\n                    end\n\n                    quest:setVar(player, 'Reissue', 1)\n                end,\n\n                [8] = function(player, csid, option, npc)\n                    local questKeyItem = getQuestKeyItem(player)\n\n                    if\n                        questKeyItem == xi.keyItem.NONE or\n                        player:hasItem(xi.item.OLDUUM_RING) or\n                        player:hasItem(xi.item.LIGHTNING_BAND) or\n                        quest:getVar(player, 'Reissue') ~= 1 or\n                        quest:getVar(player, 'Wait') > GetSystemTime()\n                    then\n                        return\n                    end\n\n                    if not npcUtil.giveItem(player, xi.item.LIGHTNING_BAND) then\n                        return\n                    end\n\n                    player:delKeyItem(questKeyItem)\n                    quest:setVar(player, 'Prog', 0)\n                    quest:setVar(player, 'Reissue', 0)\n                end,\n            },\n        },\n\n        [xi.zone.AYDEEWA_SUBTERRANE] =\n        {\n            ['Excavation_Site'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Reissue') == 1 and\n                        quest:getVar(player, 'Wait') <= GetSystemTime() and\n                        not player:hasItem(xi.item.OLDUUM_RING) and\n                        not player:hasItem(xi.item.LIGHTNING_BAND) and\n                        getQuestKeyItem(player) == xi.keyItem.NONE and\n                        npcUtil.tradeMatches(trade, { { xi.item.PICKAXE, 1 } })\n                    then\n                        if math.randomInt(1, 100) <= 50 then\n                            quest:setVar(player, 'Prog', math.randomInt(1, 3))\n\n                            return quest:progressEvent(0, { [0] = keyItems[quest:getVar(player, 'Prog')] })\n                        else\n                            player:setLocalVar('mineFail', 1)\n                            return quest:progressEvent(0, { [1] = 1 })\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [0] = function(player, csid, option, npc)\n                    if player:getLocalVar('mineFail') == 1 then\n                        player:setLocalVar('mineFail', 0)\n                    else\n                        player:addKeyItem(keyItems[quest:getVar(player, 'Prog')])\n                    end\n\n                    player:tradeComplete()\n                end,\n            },\n        },\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            ['Leypoint'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:hasItem(xi.item.OLDUUM_RING) and\n                        npcUtil.tradeMatches(trade, { { xi.item.LIGHTNING_BAND, 1 } })\n                    then\n                        if player:getFreeSlotsCount() == 0 then\n                            return quest:messageSpecial(\n                                zones[player:getZoneID()].text.ITEM_CANNOT_BE_OBTAINED,\n                                xi.item.OLDUUM_RING)\n                        else\n                            return quest:progressEvent(2)\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if player:hasItem(xi.item.LIGHTNING_BAND) then\n                        return quest:messageSpecial(zones[player:getZoneID()].text.LEYPOINT + 1, xi.item.LIGHTNING_BAND)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    if\n                        not player:hasItem(xi.item.OLDUUM_RING) and\n                        npcUtil.giveItem(player, xi.item.OLDUUM_RING)\n                    then\n                        player:tradeComplete()\n                        quest:setVar(player, 'Wait', GetSystemTime() + 60) -- 1 minute\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"}};
